19	/// Same shape as `capture_flow_e2e_test.dart`'s/`entry_detail_flow_e2e_
20	/// test.dart`'s own fake adapter, extended with [queueSseResponse] for
21	/// `ApiClient.postStream`'s `ResponseType.stream` requests — only the
22	/// transport boundary is faked.
23	///
24	/// A queued SSE response is delivered as the exact [chunks] given, each
25	/// its own separate stream emission (never pre-joined into one string) —
26	/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
27	/// `\n\n`-boundary buffering really works across genuine network chunk
28	/// boundaries, not just against a single already-complete event.
29	class _FakeHttpClientAdapter implements HttpClientAdapter {
30	  final List<RequestOptions> requests = [];
31	  final List<ResponseBody Function()> _queue = [];
32	
33	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
34	    _queue.add(
35	      () => ResponseBody.fromString(
36	        jsonEncode(body),
37	        statusCode,
38	        headers: {
39	          Headers.contentTypeHeader: [Headers.jsonContentType],
40	        },
41	      ),
42	    );
43	  }
44	
45	  void queueErrorResponse(String code, String message, {int statusCode = 503}) {
46	    queueJsonResponse(statusCode, {
47	      'code': code,
48	      'message': message,
49	      'retryable': true,
50	    });
51	  }
52	
53	  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
54	    _queue.add(
55	      () => ResponseBody(
56	        Stream.fromIterable(
57	          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
58	        ),
59	        statusCode,
60	        headers: {
61	          Headers.contentTypeHeader: ['text/event-stream'],
62	        },
63	      ),
64	    );
65	  }
66	
67	  @override
68	  Future<ResponseBody> fetch(
69	    RequestOptions options,
70	    Stream<Uint8List>? requestStream,
71	    Future<void>? cancelFuture,
72	  ) async {
73	    requests.add(options);
74	    if (_queue.isEmpty) {
75	      throw StateError(
76	        'No queued response for ${options.method} ${options.path}',
77	      );
78	    }
79	    return _queue.removeAt(0)();
80	  }
81	
82	  @override
83	  void close({bool force = false}) {}
84	}
