86	Map<String, dynamic> _sessionJson({required String id, required String updatedAt}) => {
87	  'id': id,
88	  'title': 'Nova conversa',
89	  'personaSnapshot': 'empatico',
90	  'userMessageCount': 0,
91	  'lastUserMessageAt': null,
92	  'createdAt': updatedAt,
93	  'updatedAt': updatedAt,
94	};
