96	/// End-to-end coverage for spec-6-1's chat flow, driven through the real
97	/// production object graph `sl` resolves for Home/Chat (the exact
98	/// `ChatCubit` instance `app_router.dart` gives `ChatScreen`), wired to
99	/// the real `ChatRepositoryImpl` -> `ChatRemoteDataSource` -> `ApiClient`
100	/// -> `Dio` (both real interceptors attached) -> the real `chat_sessions`/
101	/// `chat_messages` Hive boxes. Only the transport boundary and the native
102	/// plugins (secure storage, path_provider) are faked — no device/
103	/// simulator/CI exists yet (AGENTS.md).
104	///
105	/// Complements rather than duplicates this story's existing mocked tests
106	/// (`chat_cubit_test.dart` against a fake `ChatRepository`,
107	/// `chat_repository_impl_test.dart`/`chat_remote_data_source_test.dart`
108	/// against a mocked `ApiClient`): none of them drives a real SSE byte
109	/// stream through the real `ApiClient.postStream` -> `ChatRemoteDataSource`
110	/// `\n\n`-buffering -> `ChatCubit` token-append pipeline in one send, the
111	/// way the app actually does on every message.
112	///
113	/// Driven directly against `ChatCubit`'s own public API (`init`/
114	/// `sendMessage`), not through `tester.tap`/`pumpAndSettle` — same
115	/// rationale `capture_flow_e2e_test.dart` documents: these awaits span
116	/// genuine async I/O (a real Dio round trip over a faked transport), and
117	/// `pumpAndSettle` isn't guaranteed to wait for that.
118	void main() {
119	  TestWidgetsFlutterBinding.ensureInitialized();
120	
121	  const secureStorageChannel = MethodChannel(
122	    'plugins.it_nomads.com/flutter_secure_storage',
123	  );
124	  final fakeNativeStorage = <String, String>{};
125	
126	  // spec-6-3 — `sl<ChatCubit>()` below resolves the *real* `ChatCubit`,
127	  // whose constructor subscribes to the real `connectivity_plus`-backed
128	  // `ConnectivityWatcher` immediately; faked the same way
129	  // `bootstrap_integration_test.dart` fakes it, since no device/simulator
130	  // exists yet (AGENTS.md) to answer these channels for real.
131	  const connectivityMethodChannel = MethodChannel(
132	    'dev.fluttercommunity.plus/connectivity',
133	  );
134	  const connectivityEventChannel = EventChannel(
135	    'dev.fluttercommunity.plus/connectivity_status',
136	  );
137	
138	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
139	    final args = call.arguments as Map<dynamic, dynamic>;
140	    switch (call.method) {
141	      case 'write':
142	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
143	        return null;
144	      case 'read':
145	        return fakeNativeStorage[args['key'] as String];
146	      case 'delete':
147	        fakeNativeStorage.remove(args['key'] as String);
148	        return null;
149	      case 'containsKey':
150	        return fakeNativeStorage.containsKey(args['key'] as String);
151	      default:
152	        return null;
153	    }
154	  }
155	
156	  late FakePathProviderPlatform fakePathProvider;
157	  late _FakeHttpClientAdapter adapter;
158	
159	  // spec-6-3 — the real `connectivity_plus` plugin reaches this channel's
160	  // own event stream via `EventChannel.receiveBroadcastStream()`, not a
161	  // plain method call, so it must be mocked with `setMockStreamHandler`
162	  // rather than `setMockMethodCallHandler` to let a test push a live
163	  // reading. Captured on `onListen` (fired as soon as `sl<ChatCubit>()`'s
164	  // own constructor subscribes) so a test can call
165	  // `connectivityEventSink!.success([...])` to simulate a connectivity
166	  // change arriving from the OS.
167	  MockStreamHandlerEventSink? connectivityEventSink;
168	
169	  /// Pushes a live `connectivity_plus` reading and flushes the microtask
170	  /// hops between the fake event channel and `ChatCubit`'s own listener
171	  /// (the channel's `receiveBroadcastStream` -> `connectivity_plus`'s
172	  /// `distinct()` wrapper -> `ConnectivityPlusWatcher`'s own controller ->
173	  /// `ChatCubit._handleConnectivityChange`) — same `Future.delayed(Duration.
174	  /// zero)`-per-hop convention `connectivity_plus_watcher_test.dart` uses.
175	  Future<void> emitConnectivity(List<String> results) async {
176	    connectivityEventSink!.success(results);
177	    for (var i = 0; i < 5; i++) {
178	      await Future<void>.delayed(Duration.zero);
179	    }
180	  }
181	
182	  setUp(() async {
183	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
184	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
185	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
186	        .setMockMethodCallHandler(
187	          connectivityMethodChannel,
188	          (call) async => call.method == 'check' ? <String>['wifi'] : null,
189	        );
190	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
191	        .setMockStreamHandler(
192	          connectivityEventChannel,
193	          MockStreamHandler.inline(
194	            onListen: (_, events) => connectivityEventSink = events,
195	            onCancel: (_) => connectivityEventSink = null,
196	          ),
197	        );
198	    fakePathProvider = FakePathProviderPlatform();
199	    PathProviderPlatform.instance = fakePathProvider;
200	
201	    await resetCoreDependencies();
202	    await setupCoreDependencies();
203	
204	    adapter = _FakeHttpClientAdapter();
205	    sl<Dio>().httpClientAdapter = adapter;
206	
207	    // `chat-messages-send` et al. are bearer-required operations — seed a
208	    // user access token through the real `AccessTokenProvider` so the
209	    // real header interceptor has one to send.
210	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
211	  });
212	
213	  tearDown(() async {
214	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
215	        .setMockMethodCallHandler(secureStorageChannel, null);
216	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
217	        .setMockMethodCallHandler(connectivityMethodChannel, null);
218	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
219	        .setMockStreamHandler(connectivityEventChannel, null);
220	    fakeNativeStorage.clear();
221	    await Hive.close();
222	    await resetCoreDependencies();
223	    await fakePathProvider.cleanUp();
224	  });
225	
226	  test(
227	    'happy path: no existing session -> bootstrap creates one, then '
228	    'sendMessage() drives a genuine multi-chunk SSE POST to '
229	    'chat-messages-send/{sessionId} through the real pipeline, joining '
230	    'tokens split across chunk boundaries into one complete AI bubble',
231	    () async {
232	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
233	      adapter.queueJsonResponse(200, {
234	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
235	      });
236	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
237	      adapter.queueSseResponse([
238	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n',
239	        // Split mid-event: this chunk ends inside an incomplete token
240	        // event's `data:` line, the next one finishes it and immediately
241	        // opens a second event in the same chunk.
242	        'event: token\ndata: {"delta":"Ol',
243	        'á, tudo bem?"}\n\nevent: token\ndata: {"delta":" Vamos conversar."}\n\n',
244	        'event: done\ndata: {}\n\n',
245	      ]);
246	
247	      final cubit = sl<ChatCubit>();
248	      await cubit.init();
249	      expect(cubit.state, isA<ChatReady>());
250	
251	      await cubit.sendMessage('Oi, bom dia!');
252	
253	      final state = cubit.state as ChatReady;
254	      expect(state.sessionId, 'session-1');
255	      expect(state.isSending, isFalse);
256	      expect(state.messages, hasLength(2));
257	      expect(state.messages[0].role, ChatMessageRole.user);
258	      expect(state.messages[0].content, 'Oi, bom dia!');
259	      expect(state.messages[0].status, ChatMessageStatus.complete);
260	      expect(state.messages[1].role, ChatMessageRole.assistant);
261	      expect(state.messages[1].content, 'Olá, tudo bem? Vamos conversar.');
262	      expect(state.messages[1].status, ChatMessageStatus.complete);
263	
264	      expect(adapter.requests, hasLength(4));
265	      final sendRequest = adapter.requests.last;
266	      expect(
267	        sendRequest.path,
268	        sl<UrlBuilder>().build('chat-messages-send', ['session-1']),
269	      );
270	      expect(sendRequest.data, {'content': 'Oi, bom dia!'});
271	      expect(sendRequest.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
272	      expect(
273	        sendRequest.headers['Authorization'],
274	        'Bearer e2e-test-access-token',
275	      );
276	
277	      // The real write-through happened against the real `chat_sessions`
278	      // Hive box (`createSession()`'s own persist-then-return step).
279	      final sessionsBox = sl<Box<Map>>(instanceName: 'chat_sessions');
280	      expect(sessionsBox.get('session-1'), isNotNull);
281	    },
282	  );
283	
284	  test(
285	    'review finding: a second sendMessage() on the same cubit, issued '
286	    'after the first one fully completed, resolves promptly through the '
287	    'real Dio/ApiClient.postStream subscription lifecycle — proves the '
288	    'stale-_sendSubscription-nulling fix (chat_cubit.dart\'s '
289	    '_consumeStream) actually works against a real subscription, not '
290	    'only the fake-StreamController-backed one unit tests use',
291	    () async {
292	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
293	      adapter.queueJsonResponse(200, {
294	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
295	      });
296	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
297	      adapter.queueSseResponse([
298	        'event: token\ndata: {"delta":"Primeira resposta."}\n\n'
299	            'event: done\ndata: {}\n\n',
300	      ]);
301	      adapter.queueSseResponse([
302	        'event: token\ndata: {"delta":"Segunda resposta."}\n\n'
303	            'event: done\ndata: {}\n\n',
304	      ]);
305	
306	      final cubit = sl<ChatCubit>();
307	      await cubit.init();
308	
309	      await cubit.sendMessage('Primeira pergunta.');
310	      expect(
311	        (cubit.state as ChatReady).messages[1].content,
312	        'Primeira resposta.',
313	      );
314	
315	      // Without the fix, the first call's own now-finished subscription
316	      // is never cleared, so this second call's `await
317	      // _sendSubscription?.cancel()` would hang on the real subscription
318	      // — the timeout turns that hang into a clear failure instead of a
319	      // stuck test run.
320	      await cubit
321	          .sendMessage('Segunda pergunta.')
322	          .timeout(const Duration(seconds: 5));
323	
324	      final state = cubit.state as ChatReady;
325	      expect(state.messages, hasLength(4));
326	      expect(state.messages[3].content, 'Segunda resposta.');
327	      expect(state.messages[3].status, ChatMessageStatus.complete);
328	    },
329	  );
