331	  test(
332	    'mid-stream drop: a connection that closes with no done/error event '
333	    'keeps the AI bubble\'s partial text (never cleared) and marks it '
334	    'failed, with no exception escaping the cubit',
335	    () async {
336	      adapter.queueJsonResponse(200, {
337	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
338	      });
339	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
340	      adapter.queueSseResponse([
341	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n'
342	            'event: token\ndata: {"delta":"Entendo."}\n\n',
343	        // Stream ends here with no `done`/`error` event — a mid-stream
344	        // drop (I/O matrix).
345	      ]);
346	
347	      final cubit = sl<ChatCubit>();
348	      await cubit.init();
349	
350	      await cubit.sendMessage('Como você está?');
351	
352	      final state = cubit.state as ChatReady;
353	      expect(state.isSending, isFalse);
354	      expect(state.messages, hasLength(2));
355	      expect(state.messages[1].content, 'Entendo.');
356	      expect(state.messages[1].status, ChatMessageStatus.failed);
357	    },
358	  );
