360	  test(
361	    'in-band error event: an SSE `error` event with a taxonomy code marks '
362	    'the AI bubble failed and fires exactly one POST (chat-messages-send '
363	    'is excluded from transparent retry)',
364	    () async {
365	      adapter.queueJsonResponse(200, {
366	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
367	      });
368	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
369	      adapter.queueSseResponse([
370	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n'
371	            'event: error\ndata: {"code":"RATE_LIMITED","message":"Limite atingido."}\n\n',
372	      ]);
373	
374	      final cubit = sl<ChatCubit>();
375	      await cubit.init();
376	
377	      await cubit.sendMessage('Mais uma pergunta.');
378	
379	      final state = cubit.state as ChatReady;
380	      expect(state.isSending, isFalse);
381	      expect(state.messages[1].content, '');
382	      expect(state.messages[1].status, ChatMessageStatus.failed);
383	
384	      // Exactly 3 requests total (sessions-list, messages-list, the one
385	      // send) — no retry attempt behind the scenes.
386	      expect(adapter.requests, hasLength(3));
387	    },
388	  );
389	
390	  test(
391	    'spec-6-3: tap-to-retry on a failed AI bubble (its preceding user '
392	    'message already carrying a serverId) regenerates that exact bubble '
393	    'in place through the real chat-messages-retry endpoint — no new '
394	    'bubble pair, no re-send of the question',
395	    () async {
396	      adapter.queueJsonResponse(200, {
397	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
398	      });
399	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
400	      // `message_created` arrives (capturing the serverId), then the
401	      // stream drops mid-token with no `done`/`error` — I/O matrix's
402	      // "Tap retry, normal" precondition.
403	      adapter.queueSseResponse([
404	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n'
405	            'event: token\ndata: {"delta":"Entendo."}\n\n',
406	      ]);
407	      adapter.queueSseResponse([
408	        'event: token\ndata: {"delta":"Resposta regenerada."}\n\n'
409	            'event: done\ndata: {}\n\n',
410	      ]);
411	
412	      final cubit = sl<ChatCubit>();
413	      await cubit.init();
414	      await cubit.sendMessage('Como você está?');
415	
416	      var state = cubit.state as ChatReady;
417	      expect(state.messages, hasLength(2));
418	      final userMessageId = state.messages[0].id;
419	      final aiMessageId = state.messages[1].id;
420	      expect(state.messages[1].status, ChatMessageStatus.failed);
421	
422	      await cubit.retryMessage(aiMessageId);
423	
424	      state = cubit.state as ChatReady;
425	      expect(state.messages, hasLength(2));
426	      expect(state.messages[0].id, userMessageId);
427	      expect(state.messages[0].content, 'Como você está?');
428	      expect(state.messages[1].id, aiMessageId);
429	      expect(state.messages[1].content, 'Resposta regenerada.');
430	      expect(state.messages[1].status, ChatMessageStatus.complete);
431	
432	      final retryRequest = adapter.requests.last;
433	      expect(
434	        retryRequest.path,
435	        sl<UrlBuilder>().build('chat-messages-retry', [
436	          'session-1',
437	          'srv-msg-1',
438	        ]),
439	      );
440	    },
441	  );
442	
443	  test(
444	    'spec-6-3: tap-to-retry on a failed bubble whose stream dropped '
445	    'before message_created ever arrived falls back to a full '
446	    'chat-messages-send resend of the same question into the same '
447	    'bubble slot — never calls chat-messages-retry with no serverId',
448	    () async {
449	      adapter.queueJsonResponse(200, {
450	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
451	      });
452	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
453	      // Drops before `message_created` ever arrives — the user message
454	      // never gains a serverId (I/O matrix: "Tap retry, no serverId").
455	      adapter.queueSseResponse(['event: token\ndata: {"delta":"Oi."}\n\n']);
456	      adapter.queueSseResponse([
457	        'event: token\ndata: {"delta":"Resposta via resend."}\n\n'
458	            'event: done\ndata: {}\n\n',
459	      ]);
460	
461	      final cubit = sl<ChatCubit>();
462	      await cubit.init();
463	      await cubit.sendMessage('Pergunta original.');
464	
465	      var state = cubit.state as ChatReady;
466	      expect(state.messages, hasLength(2));
467	      final userMessageId = state.messages[0].id;
468	      final aiMessageId = state.messages[1].id;
469	      expect(state.messages[1].status, ChatMessageStatus.failed);
470	
471	      await cubit.retryMessage(aiMessageId);
472	
473	      state = cubit.state as ChatReady;
474	      expect(state.messages, hasLength(2));
475	      expect(state.messages[0].id, userMessageId);
476	      expect(state.messages[1].id, aiMessageId);
477	      expect(state.messages[1].content, 'Resposta via resend.');
478	      expect(state.messages[1].status, ChatMessageStatus.complete);
479	
480	      expect(
481	        adapter.requests.every((r) => !r.path.contains('chat-messages-retry')),
482	        isTrue,
483	      );
484	      final sendUrl = sl<UrlBuilder>().build('chat-messages-send', ['session-1']);
485	      expect(adapter.requests.where((r) => r.path == sendUrl).length, 2);
486	    },
487	  );
