411	  /// is in flight"), so this is a no-op while a send/retry is already in
412	  /// flight — and, like [sendMessage] (review finding), a no-op while
413	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
414	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
415	  /// alone, so it needs this exact same guard to honor the offline banner.
416	  Future<void> retryMessage(String aiMessageId) async {
417	    final current = state;
418	    if (current is! ChatReady) {
419	      return;
420	    }
421	    if (_isSending || current.isOffline) {
422	      return;
423	    }
424	    final messages = current.messages;
425	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
426	    // Review finding: defensively checks `role` too, even though only an
427	    // assistant message ever reaches `failed` status today — matches this
428	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
429	    // not-found/structurally-impossible case).
430	    if (aiIndex == -1 ||
431	        messages[aiIndex].role != ChatMessageRole.assistant ||
432	        messages[aiIndex].status != ChatMessageStatus.failed) {
433	      return;
434	    }
435	    ChatUiMessage? userMessage;
436	    for (var i = aiIndex - 1; i >= 0; i--) {
437	      if (messages[i].role == ChatMessageRole.user) {
438	        userMessage = messages[i];
439	        break;
440	      }
441	    }
442	    if (userMessage == null) {
443	      return;
444	    }
445	
446	    _isSending = true;
447	    emit(
448	      current.copyWith(
449	        messages: [
450	          for (final message in current.messages)
451	            if (message.id == aiMessageId)
452	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
453	            else
454	              message,
455	        ],
456	        isSending: true,
457	      ),
458	    );
459	
460	    final serverId = userMessage.serverId;
461	    final stream = serverId == null
462	        ? _repository.sendMessage(current.sessionId, userMessage.content)
463	        : _repository.retryMessage(current.sessionId, serverId);
464	    await _consumeStream(
465	      stream,
466	      userMessageId: userMessage.id,
467	      aiMessageId: aiMessageId,
468	    );
469	  }
470	
471	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
472	  /// helper" extends to this subscribe-and-wait shape too, not just
473	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
474	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
475	  /// resolves once the stream ends (`done`, an in-band error, or a
476	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
477	  /// either way via [_finishSending].
478	  Future<void> _consumeStream(
479	    Stream<Either<Failure, ChatStreamEvent>> stream, {
480	    required String userMessageId,
481	    required String aiMessageId,
482	  }) async {
483	    await _sendSubscription?.cancel();
484	    final completer = Completer<void>();
485	    _sendCompleter = completer;
486	    _sendSubscription = stream.listen(
487	      (event) {
488	        event.match(
489	          (failure) => _markFailed(aiMessageId),
490	          (streamEvent) =>
491	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
492	        );
493	      },
494	      onError: (Object _, StackTrace _) {
495	        // RNF09: no exception escapes the cubit — a stream-level error
496	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
497	        // unmapped) still only fails the bubble, never crashes.
498	        _markFailed(aiMessageId);
499	        _finishSending();
500	        if (!completer.isCompleted) {
501	          completer.complete();
502	        }
503	        // Review finding: a stale, already-done subscription reference
504	        // left on `_sendSubscription` made a *later* send/retry's own
505	        // `await _sendSubscription?.cancel()` above hang indefinitely in
506	        // practice (observed via a widget test driving two sends back to
507	        // back) — cleared here (and in the `onDone` branch below)
508	        // exactly where this stream's own lifecycle actually ends,
509	        // rather than relying on cancelling an already-finished
510	        // subscription being an instant no-op.
511	        _sendSubscription = null;
512	        _sendCompleter = null;
513	      },
514	      onDone: () {
515	        _finishSending();
516	        if (!completer.isCompleted) {
517	          completer.complete();
518	        }
519	        _sendSubscription = null;
520	        _sendCompleter = null;
521	      },
522	      cancelOnError: false,
523	    );
524	    await completer.future;
525	  }
526	
527	  /// Clears both the internal re-entrancy guard and the UI-facing
528	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
529	  /// an in-band error, or a stream-level error) — the single place both
530	  /// flip back together.
531	  void _finishSending() {
532	    _isSending = false;
533	    if (isClosed) {
534	      return;
535	    }
536	    final current = state;
537	    if (current is ChatReady) {
538	      emit(current.copyWith(isSending: false));
539	    }
540	  }
541	
542	  void _applyStreamEvent(
543	    String userMessageId,
544	    String aiMessageId,
545	    ChatStreamEvent event,
546	  ) {
547	    if (isClosed) {
548	      return;
549	    }
550	    final current = state;
551	    if (current is! ChatReady) {
552	      return;
553	    }
554	    switch (event) {
555	      case ChatMessageCreatedEvent(userMessageId: final serverId):
556	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
557	        // now this story's first consumer, captured onto the matching
558	        // local user bubble by id so a later `retryMessage` call (on the
559	        // AI bubble this same send produces) has a non-null `serverId` to
560	        // key `chat-messages-retry` off of.
561	        emit(
562	          current.copyWith(
563	            messages: [
564	              for (final message in current.messages)
565	                if (message.id == userMessageId)
566	                  message.copyWith(serverId: serverId)
567	                else
568	                  message,
569	            ],
570	          ),
571	        );
572	      case ChatTokenEvent(delta: final delta):
573	        emit(
574	          current.copyWith(
575	            messages: [
576	              for (final message in current.messages)
577	                if (message.id == aiMessageId)
578	                  message.copyWith(content: message.content + delta)
579	                else
580	                  message,
581	            ],
582	          ),
583	        );
584	      case ChatDoneEvent():
585	        emit(
586	          current.copyWith(
587	            messages: [
588	              for (final message in current.messages)
589	                if (message.id == aiMessageId)
590	                  message.copyWith(status: ChatMessageStatus.complete)
591	                else
592	                  message,
593	            ],
594	          ),
595	        );
596	    }
597	  }
598	
599	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
600	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
601	  /// as-is (never cleared, Boundaries).
602	  void _markFailed(String aiMessageId) {
603	    if (isClosed) {
604	      return;
605	    }
606	    final current = state;
607	    if (current is! ChatReady) {
608	      return;
609	    }
610	    emit(
611	      current.copyWith(
612	        messages: [
613	          for (final message in current.messages)
614	            if (message.id == aiMessageId)
615	              message.copyWith(status: ChatMessageStatus.failed)
616	            else
617	              message,
618	        ],
619	      ),
620	    );
621	  }
622	
623	  /// spec-6-4 (RF10) — Boundaries: the bookmark affordance exists only on
624	  /// [ChatMessageRole.user] bubbles; tapping it turns that exact message
625	  /// into a journal Entry (`source: EntrySource.chat`) through
626	  /// [_saveChatMessageAsEntryUseCase] only — never `EntriesRepository`
627	  /// directly (AGENTS.md's RF10 rule). A no-op (I/O & Edge-Case Matrix)
628	  /// when: [state] isn't [ChatReady]; [messageId] isn't found; its role
629	  /// isn't [ChatMessageRole.user]; its [ChatUiMessage.serverId] is still
630	  /// `null` (mirrors [retryMessage]'s own guard — the backend id a save
631	  /// sends as `chatMessageId`, Boundaries); its [ChatUiMessage.
632	  /// bookmarkState] is already [BookmarkSaved] (client-side no-op — a
633	  /// repeat save is itself idempotent at the backend, Boundaries) or
634	  /// already [BookmarkSaving] (re-entrancy guard, scoped to this one
635	  /// message — [_isSending] stays scoped to send/retry only, never shared
636	  /// with this guard).
637	  Future<void> bookmarkMessage(String messageId) async {
638	    final current = state;
639	    if (current is! ChatReady) {
640	      return;
641	    }
642	    final index = current.messages.indexWhere(
643	      (message) => message.id == messageId,
644	    );
645	    if (index == -1) {
646	      return;
647	    }
648	    final message = current.messages[index];
649	    final serverId = message.serverId;
650	    if (message.role != ChatMessageRole.user ||
651	        serverId == null ||
652	        message.bookmarkState is BookmarkSaved ||
653	        message.bookmarkState is BookmarkSaving) {
654	      return;
655	    }
656	
657	    // Boundaries: both of this method's own emit() calls check isClosed
658	    // first — not just the one after the await below.
659	    if (isClosed) {
660	      return;
661	    }
662	    _bookmarkStateByServerId[serverId] = const BookmarkState.saving();
663	    emit(
664	      current.copyWith(
665	        messages: [
666	          for (final existing in current.messages)
667	            if (existing.id == messageId)
668	              existing.copyWith(bookmarkState: const BookmarkState.saving())
669	            else
670	              existing,
671	        ],
672	      ),
673	    );
674	
675	    final sideEffectResult = await isolatedSideEffect(
676	      () => _saveChatMessageAsEntry(
677	        content: message.content,
678	        chatMessageId: serverId,
679	      ),
680	    );
681	    // Flattens isolatedSideEffect's own outer Either (Left only on a
682	    // thrown exception, mapped to malformedResponse — I/O matrix: "Side-
683	    // effect throws") with the use case's own inner Either (Left on a
684	    // normal, non-thrown save failure — I/O matrix: "Save fails") into
685	    // one plain Either<Failure, Entry>, so both scenarios flip the bubble
686	    // to the same retryable error state via the one match() below.
687	    final result = sideEffectResult.match(
688	      (failure) => left(failure),
689	      (inner) => inner,
690	    );
691	
692	    final resolvedState = result.match(
693	      (failure) => BookmarkState.error(failure),
694	      (_) => const BookmarkState.saved(),
695	    );
696	    // Review fix (round 2) — written through to the serverId-keyed map
697	    // unconditionally (even if the live [ChatReady] below has since moved
698	    // on to a different session), so the outcome is never lost; re-
699	    // entering any session carrying this message picks it back up via
700	    // [_fromDomain].
701	    _bookmarkStateByServerId[serverId] = resolvedState;
702	
703	    if (isClosed) {
704	      return;
705	    }
706	    final latest = state;
707	    if (latest is! ChatReady) {
708	      return;
709	    }
710	    // Matched by `serverId`, not the in-session `messageId` — the latter
711	    // is stale once [switchSession]/[startNewSession] reloads this exact
712	    // session's history mid-save, which re-derives every message's own
713	    // `id` from the server (`_fromDomain`) instead of keeping the local
714	    // id this call started with.
715	    final stillVisible = latest.messages.any(
716	      (existing) => existing.serverId == serverId,
717	    );
718	    if (!stillVisible) {
719	      return;
720	    }
721	    emit(
722	      latest.copyWith(
723	        messages: [
724	          for (final existing in latest.messages)
725	            if (existing.serverId == serverId)
726	              existing.copyWith(bookmarkState: resolvedState)
727	            else
728	              existing,
729	        ],
730	      ),
731	    );
732	  }
733	
734	  /// [bookmarkMessage]'s own save call — forwards to
735	  /// [_saveChatMessageAsEntryUseCase] verbatim, wrapped by
736	  /// [isolatedSideEffect] at the call site above (never here) so a
737	  /// synchronous throw from the use case itself is still caught.
738	  Future<Either<Failure, Entry>> _saveChatMessageAsEntry({
739	    required String content,
740	    required String chatMessageId,
741	  }) => _saveChatMessageAsEntryUseCase(
742	    content: content,
743	    chatMessageId: chatMessageId,
744	  );
745	
746	  String _nextLocalId() => 'local-${_localIdCounter++}';
747	
748	  /// spec-6-3 — [_connectivityWatcher]'s own listener: [isOnline] `true`
749	  /// means the device currently has connectivity. Always updates
750	  /// [_isOffline] (even outside [ChatReady] — see [_isOffline]'s own doc),
751	  /// but only *emits* when already [ChatReady] and the value actually
752	  /// changed, so an unrelated repeated emission of the same status (e.g.
753	  /// a plugin re-announcing "still online") never triggers a spurious
754	  /// rebuild.
755	  void _handleConnectivityChange(bool isOnline) {
756	    _isOffline = !isOnline;
757	    if (isClosed) {
758	      return;
759	    }
760	    final current = state;
761	    if (current is ChatReady && current.isOffline != _isOffline) {
762	      emit(current.copyWith(isOffline: _isOffline));
763	    }
764	  }
765	
766	  /// Review finding: "Cross-session stream leakage" — [switchSession]/
767	  /// [startNewSession] call this before touching anything else whenever
768	  /// they're about to make a *different* session active, so a response
769	  /// still streaming into the session being left behind can never go on
770	  /// to mutate the one that replaces it. Exactly [close]'s own cleanup
771	  /// below (cancel the subscription, resolve the stranded [sendMessage]
772	  /// caller, clear the re-entrancy guard), just without closing the cubit
773	  /// itself — a no-op when nothing is actually in flight.
774	  Future<void> _cancelInFlightSend() async {
775	    if (!_isSending) {
776	      return;
777	    }
778	    await _sendSubscription?.cancel();
779	    _sendSubscription = null;
780	    final completer = _sendCompleter;
781	    if (completer != null && !completer.isCompleted) {
782	      completer.complete();
783	    }
784	    _sendCompleter = null;
785	    _isSending = false;
786	  }
787	
788	  @override
789	  Future<void> close() {
790	    _connectivitySubscription?.cancel();
791	    _sendSubscription?.cancel();
792	    final completer = _sendCompleter;
793	    if (completer != null && !completer.isCompleted) {
794	      completer.complete();
795	    }
796	    _sendCompleter = null;
797	    return super.close();
798	  }
799	}
